import os

# Check if the directory exists and is writable
def is_directory_writable(directory):
    return os.access(directory, os.W_OK)

# Check if the directory is owned by the current user
def is_directory_owned_by_current_user(directory):
    try:
        stat = os.stat(directory)
        return stat.st_uid == os.getuid()
    except OSError:
        return False

# Example usage
directory = "/path/to/secure/directory"
print("Directory exists:", os.path.exists(directory))
print("Directory is writable:", is_directory_writable(directory))
print("Directory is owned by current user:", is_directory_owned_by_current_user(directory))
